using System.Drawing;using System.Windows.Forms;using AshkanPharmacy.Core;using AshkanPharmacy.Models;
namespace AshkanPharmacy.Forms { public class HeldSalesForm:Form { public HeldSale SelectedSale{get;private set;} ListBox list=new ListBox();
 public HeldSalesForm(){Text=Localization.Persian?"فروش‌های معلق":"Held Sales";StartPosition=FormStartPosition.CenterParent;ClientSize=new Size(560,470);BackColor=Color.FromArgb(230,240,244);list.SetBounds(25,70,510,300);foreach(var h in HeldSaleService.All())list.Items.Add(new Item(h));var take=new AccentButton{Text=Localization.Persian?"ادامه فروش":"Resume sale",Left=350,Top=390,Width=185,Height=46,BackColor=Theme.Teal,ForeColor=Color.White};take.Click+=(s,e)=>{var i=list.SelectedItem as Item;if(i==null)return;SelectedSale=HeldSaleService.Take(i.Value.Id);DialogResult=DialogResult.OK;Close();};Controls.Add(new Label{Text=Text,Left=25,Top=22,Width=400,Height=35,Font=Theme.Font(17,FontStyle.Bold),ForeColor=Theme.Navy});Controls.Add(list);Controls.Add(take);}
 class Item{public HeldSale Value;public Item(HeldSale h){Value=h;}public override string ToString(){return "#"+Value.Id+" — "+Value.Label+" — "+Value.HeldAt.ToString("HH:mm")+" — "+Value.Lines.Count+" items";}}
 } }